    [Fact]
    public void Flex_grow_less_than_factor_one() {
        using var tree = new LayoutTree();

        var root = tree.CreateNode();
        tree.SetPositionType(root, PositionType.Absolute);
        tree.SetDimension(root, Dimension.Height, StyleLength.Points(500.0f));
        tree.SetDimension(root, Dimension.Width, StyleLength.Points(200.0f));

        var rootChild0 = tree.CreateNode();
        tree.SetFlexGrow(rootChild0, 0.2f);
        tree.SetFlexBasis(rootChild0, StyleLength.Points(40.0f));
        tree.InsertChild(root, rootChild0, 0);

        var rootChild1 = tree.CreateNode();
        tree.SetFlexGrow(rootChild1, 0.2f);
        tree.InsertChild(root, rootChild1, 1);

        var rootChild2 = tree.CreateNode();
        tree.SetFlexGrow(rootChild2, 0.4f);
        tree.InsertChild(root, rootChild2, 2);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(500.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(132.0f, tree.GetHeight(rootChild0), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild1), Tolerance);
        Assert.Equal(132.0f, tree.GetTop(rootChild1), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild1), Tolerance);
        Assert.Equal(92.0f, tree.GetHeight(rootChild1), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild2), Tolerance);
        Assert.Equal(224.0f, tree.GetTop(rootChild2), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild2), Tolerance);
        Assert.Equal(184.0f, tree.GetHeight(rootChild2), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(500.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(132.0f, tree.GetHeight(rootChild0), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild1), Tolerance);
        Assert.Equal(132.0f, tree.GetTop(rootChild1), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild1), Tolerance);
        Assert.Equal(92.0f, tree.GetHeight(rootChild1), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild2), Tolerance);
        Assert.Equal(224.0f, tree.GetTop(rootChild2), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild2), Tolerance);
        Assert.Equal(184.0f, tree.GetHeight(rootChild2), Tolerance);
    }
